from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class UPlaneTraceInfo(SchemaObject):
    nr_cell_dns = SchemaField(name="nrCellDns", many=True)
    trace_id = SchemaField(name="traceId", not_null=True)

    trace_type = SchemaField(name="traceType", not_null=True)
    target_component = SchemaField(name="targetComponent", not_null=True)
    status = SchemaField(name="status", not_null=True)

    def __init__(self, nr_cell_dns, trace_id, trace_type, target_component, status):
        self.nr_cell_dns = nr_cell_dns
        self.trace_id = trace_id
        self.trace_type = trace_type
        self.target_component = target_component
        self.status = status

        super(UPlaneTraceInfo, self).__init__()
